import { IMAGE_LOADER, type ImageLoaderConfig } from '@angular/common';
import { type Provider } from '@angular/core';
import manifest from '../../assets/img/manifest.json';

/**
 * Responsive images for NgOptimizedImage, generated by `pnpm images` from the masters in images/.
 *
 * Templates pass an image name as `ngSrc` and its `srcset` as `ngSrcset`; the loader below turns
 * each (name, width) pair into the URL of the matching WebP variant, which Vite fingerprints.
 */
export type ImageName = keyof typeof manifest;

export interface SiteImage {
  readonly name: ImageName;
  /** Intrinsic size of the master; NgOptimizedImage uses it for the aspect ratio. */
  readonly width: number;
  readonly height: number;
  /** Widths available for this image, in the `ngSrcset` format ("160w, 320w, …"). */
  readonly srcset: string;
}

/** Used when the browser asks for `src` without a width: sharp enough for most layouts. */
const DEFAULT_WIDTH = 1280;

const urls = import.meta.glob<string>('../../assets/img/*.webp', { eager: true, import: 'default' });

function variantUrl(name: ImageName, width: number): string {
  const url = urls[`../../assets/img/${name}-${width}.webp`];
  if (!url) throw new Error(`Missing image variant ${name}-${width}. Run pnpm images.`);
  return url;
}

export function siteImage(name: ImageName): SiteImage {
  const { width, height, widths } = manifest[name];
  return { name, width, height, srcset: widths.map(candidate => `${candidate}w`).join(', ') };
}

/** The smallest variant at least as wide as requested, or the largest one there is. */
export function imageUrl(name: ImageName, requested = DEFAULT_WIDTH): string {
  const { widths } = manifest[name];
  const width = widths.find(candidate => candidate >= requested) ?? widths.at(-1)!;
  return variantUrl(name, width);
}

/** A complete `srcset` for a plain `<img>`, where NgOptimizedImage does not fit (decorative copies). */
export function imageSrcset(name: ImageName): string {
  return manifest[name].widths.map(width => `${variantUrl(name, width)} ${width}w`).join(', ');
}

function isImageName(value: string): value is ImageName {
  return Object.hasOwn(manifest, value);
}

export function provideSiteImages(): Provider {
  return {
    provide: IMAGE_LOADER,
    useValue: ({ src, width }: ImageLoaderConfig) => {
      if (!isImageName(src)) throw new Error(`Unknown image "${src}". Add it to images/ and run pnpm images.`);
      return imageUrl(src, width);
    },
  };
}
